// Parse the Haiku JSON response and expose flat fields for the 3 Save nodes.
// Defensive: try common field-name variants, and if a field is still missing
// save a diagnostic placeholder so the workflow completes and Ian can see in
// Notion what Haiku actually returned. Social drafts are secondary to the
// blog PR itself, never block the workflow on a flaky Haiku response.
const response = $input.first().json;
const carry = $('Carry PR Info').first().json;

if (!response.content || !Array.isArray(response.content) || !response.content[0]?.text) {
  throw new Error('Generate Social Outputs returned malformed response: ' + JSON.stringify(response).substring(0, 500));
}

const raw = response.content[0].text.trim();
const jsonMatch = raw.match(/\{[\s\S]*\}/);
if (!jsonMatch) {
  throw new Error('Could not find JSON in social outputs response. Raw: ' + raw.substring(0, 500));
}

let parsed;
try {
  parsed = JSON.parse(jsonMatch[0]);
} catch (err) {
  throw new Error('Social outputs JSON parse failed: ' + err.message + '. Raw: ' + jsonMatch[0].substring(0, 500));
}

function pickField(obj, names) {
  for (const n of names) {
    const v = obj[n];
    if (typeof v === 'string' && v.trim().length > 0) return v;
  }
  return null;
}

const fields = {
  twitter: pickField(parsed, ['twitter', 'twitter_thread', 'tweet', 'tweets', 'x', 'x_thread']),
  linkedin: pickField(parsed, ['linkedin', 'linkedin_post', 'li_post']),
};

const stopReason = response.stop_reason || 'unknown';
const truncatedNote = stopReason === 'max_tokens' ? ' (Haiku response truncated by max_tokens)' : '';
const keys = Object.keys(parsed).join(', ') || '(none)';
const sample = jsonMatch[0].substring(0, 300);

for (const f of ['twitter', 'linkedin']) {
  if (!fields[f]) {
    fields[f] = '[Generation incomplete' + truncatedNote + '. Missing field: ' + f + '. Haiku returned keys: ' + keys + '. Regenerate manually. Raw sample: ' + sample + ']';
  }
}

// Deterministic link guarantee (never trust a prompt rule for a hard invariant):
// every social draft must end up containing the live post URL. Note the live URL
// is filename-based (date prefix included), NOT the bare title slug.
const postUrl = carry.siteBaseUrl + '/blog/' + String(carry.filename || '').replace(/\.mdx$/, '') + '/';
for (const f of ['twitter', 'linkedin']) {
  if (!fields[f].includes(postUrl)) {
    fields[f] = fields[f].replace(/\s+$/, '') + '\n\nFull post: ' + postUrl;
  }
}

// Notion rich_text hard-caps at 2000 chars per object. Cramming a whole
// multi-paragraph draft into one block silently dropped the tail (CTA + URL).
// Split into <=1900-char paragraph blocks on paragraph/line boundaries so the
// full draft survives; the 3 Save nodes concat these onto their callout.
const NOTION_MAX = 1900;
function toBlocks(text) {
  const mk = (s) => ({ object: 'block', type: 'paragraph', paragraph: { rich_text: [{ type: 'text', text: { content: s } }] } });
  const out = [];
  const push = (s) => { const t = String(s).replace(/\s+$/, ''); if (t.trim()) out.push(mk(t)); };
  const paras = String(text || '').split(/\n{2,}/);
  let buf = '';
  const flush = () => { if (buf) { push(buf); buf = ''; } };
  for (const p of paras) {
    if (!p.trim()) continue;
    if (p.length > NOTION_MAX) {
      flush();
      let line = '';
      for (const ln of p.split('\n')) {
        if (line && (line.length + 1 + ln.length) > NOTION_MAX) { push(line); line = ln; }
        else { line = line ? line + '\n' + ln : ln; }
        while (line.length > NOTION_MAX) { push(line.slice(0, NOTION_MAX)); line = line.slice(NOTION_MAX); }
      }
      if (line) push(line);
      continue;
    }
    if (!buf) buf = p;
    else if (buf.length + 2 + p.length <= NOTION_MAX) buf = buf + '\n\n' + p;
    else { flush(); buf = p; }
  }
  flush();
  return out.length ? out : [mk(String(text || '').slice(0, NOTION_MAX))];
}
const twitterBlocks = toBlocks(fields.twitter);
const linkedinBlocks = toBlocks(fields.linkedin);

return [{ json: { ...carry, ...fields, twitterBlocks, linkedinBlocks } }];

// Sum Anthropic token usage across the 3 Claude calls in this run and compute
// an estimated USD cost. Pricing per 1M tokens (claude-api skill, 2026-06-11):
// Sonnet 4.6 $3 in / $15 out; Haiku 4.5 $1 in / $5 out. Cache multipliers on the
// input rate: 5-min cache write 1.25x, cache read 0.1x.
function usageOf(j) {
  const u = (j && j.usage) || {};
  return {
    inp: u.input_tokens || 0,
    out: u.output_tokens || 0,
    cw: u.cache_creation_input_tokens || 0,
    cr: u.cache_read_input_tokens || 0,
  };
}
function costOf(u, inRate, outRate) {
  return (u.inp * inRate + u.cw * inRate * 1.25 + u.cr * inRate * 0.1 + u.out * outRate) / 1e6;
}
let draftJson = {}, humanJson = {}, socialJson = {}, carry = {};
try { draftJson = $('Generate Draft').first().json || {}; } catch (e) {}
try { humanJson = $('Humanize').first().json || {}; } catch (e) {}
try { socialJson = $('Generate Social Outputs').first().json || {}; } catch (e) {}
try { carry = $('Parse Social Outputs').first().json || {}; } catch (e) {}
const draft = usageOf(draftJson), human = usageOf(humanJson), social = usageOf(socialJson);
const SONNET_IN = 3, SONNET_OUT = 15, HAIKU_IN = 1, HAIKU_OUT = 5;
const costDraft = costOf(draft, SONNET_IN, SONNET_OUT);
const costHuman = costOf(human, SONNET_IN, SONNET_OUT);
const costSocial = costOf(social, HAIKU_IN, HAIKU_OUT);
const total = costDraft + costHuman + costSocial;
const sonnetIn = draft.inp + draft.cw + draft.cr + human.inp + human.cw + human.cr;
const sonnetOut = draft.out + human.out;
const haikuIn = social.inp + social.cw + social.cr;
const haikuOut = social.out;
const cacheRead = draft.cr + human.cr + social.cr;
function k(n) { return n >= 1000 ? (n / 1000).toFixed(1) + 'k' : String(n); }
const title = carry.title || carry.blogTopic || 'post';
let costLine = ':moneybag: *Cost ~$' + total.toFixed(3) + '* for "' + title + '"  |  ' +
  'Sonnet ' + k(sonnetIn) + ' in / ' + k(sonnetOut) + ' out  |  ' +
  'Haiku ' + k(haikuIn) + ' in / ' + k(haikuOut) + ' out';
if (cacheRead > 0) costLine = costLine + '  |  ' + k(cacheRead) + ' cache-read';
return [{ json: Object.assign({}, carry, {
  costLine: costLine,
  costUsd: Number(total.toFixed(4)),
  costBreakdown: {
    draft: Number(costDraft.toFixed(4)),
    humanize: Number(costHuman.toFixed(4)),
    social: Number(costSocial.toFixed(4)),
  },
  tokens: { sonnetIn: sonnetIn, sonnetOut: sonnetOut, haikuIn: haikuIn, haikuOut: haikuOut },
}) }];

// PR #88 failure class: a max_tokens-truncated draft flows into Humanize and ships
// a broken MDX file into a PR that then fails QA for weeks. Fail the run here instead;
// the workflow's errorWorkflow backstop pings Slack.
const r = $input.first().json;
if (r.stop_reason === 'max_tokens') {
  throw new Error('Generate Draft hit max_tokens (draft truncated mid-post). Topic: ' + $('Parse Topic').first().json.blogTopic);
}
if (!r.content || !Array.isArray(r.content) || !r.content[0]?.text) {
  throw new Error('Generate Draft returned malformed response: ' + JSON.stringify(r).substring(0, 300));
}
return $input.all();

// S-1b engine slug feed: build the EXACT valid internal-link targets for
// Generate Draft. NO network here — reads the two fetch nodes and fail-softs to
// empty lists on any gap (which makes the prompt omit the mesh + the Parse Draft
// guard fail-open for that list).
const tr = (() => { try { return $('Fetch Tools Registry').first().json; } catch (e) { return {}; } })();
const toolsSrc = tr.body ?? tr.data ?? (typeof tr === 'string' ? tr : '');
const br = (() => { try { return $('Fetch Blog List').first().json; } catch (e) { return {}; } })();
const blogArr = Array.isArray(br.body) ? br.body : Array.isArray(br.data) ? br.data : Array.isArray(br) ? br : [];

// Hub slugs from tools.ts (quote-agnostic; mirrors qa/registry.mjs).
const hubSlugs = [...new Set([...String(toolsSrc).matchAll(/slug:\s*['"]([a-z0-9-]+)['"]/g)].map((m) => m[1]))];

// Recent post slugs: date-prefixed .mdx/.md filenames, newest first, cap 12.
const files = blogArr.map((f) => f && f.name).filter(Boolean);
const dated = files.filter((n) => /^\d{4}-\d{2}-\d{2}-.+\.mdx?$/.test(n)).sort().reverse().slice(0, 12);
const postSlugs = dated.map((n) => n.replace(/\.mdx?$/, ''));

// Readable topic label from the slug (drop the date, title-case the rest) so the
// model can judge relevance without fetching each file.
const label = (slug) => slug.replace(/^\d{4}-\d{2}-\d{2}-/, '').replace(/-/g, ' ').replace(/\b\w/g, (c) => c.toUpperCase());
const recentPostsList = postSlugs.map((s) => `- ${s} (${label(s)})`).join('\n');

return [{ json: {
  hubSlugs,
  hubSlugsCsv: hubSlugs.join(', '),
  postSlugs,
  recentPostsList: recentPostsList || '(none available)',
} }];
